     7→#include <zephyr/kernel.h>
     8→#include <zephyr/drivers/pinctrl.h>
     9→#include <zephyr/arch/common/sys_io.h>
    10→
    11→#define BK7258_GPIO_CFG_BASE        0x44000400U
    12→#define BK7258_GPIO_FUNC_MODE_BASE  0x440100C0U
    13→
    14→#define BK_GPIO_CFG_OFF(gpio)       ((gpio) * 4U)
    15→#define BK_GPIO_BIT_2ND_FUNC        BIT(6)
    16→#define BK_GPIO_BIT_PULL_MODE_EN    BIT(5)
    17→#define BK_GPIO_BIT_PULL_MODE       BIT(4)
    18→#define BK_GPIO_BIT_OUTPUT_EN       BIT(3) /* Active low */
    19→#define BK_GPIO_BIT_INPUT_EN        BIT(2)
    20→
    21→int pinctrl_configure_pins(const pinctrl_soc_pin_t *pins,
    22→                        uint8_t pin_cnt,
    23→                        uintptr_t reg)
    24→{
    25→    ARG_UNUSED(reg);
    26→
    27→    for (uint8_t i = 0; i < pin_cnt; i++) {
    28→        pinctrl_soc_pin_t p = pins[i];
    29→        uint8_t gpio = p & 0x3f;
    30→        uint8_t func = (p >> 8) & 0x0f;
    31→        uint32_t val;
    32→
    33→        val = sys_read32(BK7258_GPIO_CFG_BASE + BK_GPIO_CFG_OFF(gpio));
    34→
    35→        if (p & BK7258_FLAG_SECOND_FUNC) {
    36→            val |= BK_GPIO_BIT_2ND_FUNC;
    37→        }
    38→        if (p & BK7258_FLAG_OUTPUT) {
    39→            val &= ~BK_GPIO_BIT_OUTPUT_EN;
    40→        }
    41→        if (p & BK7258_FLAG_INPUT) {
    42→            val |= BK_GPIO_BIT_INPUT_EN;
    43→        }
    44→        if (p & BK7258_FLAG_PULL_UP) {
    45→            val |= BK_GPIO_BIT_PULL_MODE_EN | BK_GPIO_BIT_PULL_MODE;
    46→        }
    47→        if (p & BK7258_FLAG_PULL_DOWN) {
    48→            val |= BK_GPIO_BIT_PULL_MODE_EN;
    49→            val &= ~BK_GPIO_BIT_PULL_MODE;
    50→        }
    51→
    52→        sys_write32(val, BK7258_GPIO_CFG_BASE + BK_GPIO_CFG_OFF(gpio));
    53→
    54→        /*
    55→         * BK7258 peripheral_mode accepts 0 as a valid function value.
    56→         * For example, UART1_TX/RX on GPIO0/GPIO1 have func=0, so
    57→         * peripheral_mode must always be written regardless of func.
    58→         * Write the func value from pinmux on every pin configuration.
    59→         */
    60→        {
    61→            uint8_t group = gpio / 8;
    62→            uint8_t shift = (gpio % 8) * 4;
    63→            uint32_t addr = BK7258_GPIO_FUNC_MODE_BASE + group * 4;
    64→            uint32_t fval = sys_read32(addr);
    65→
    66→            fval &= ~(0x0fU << shift);
    67→            fval |= ((uint32_t)func << shift);
    68→            sys_write32(fval, addr);
    69→        }
    70→    }
    71→
    72→    return 0;
    73→}
