17	#define AMEBA_GPIO_PINNAME(port, pin) (((port) << 5) | ((pin) & 0x1F))
18	
19	static int ameba_configure_pin(const pinctrl_soc_pin_t *pin)
20	{
21		uint32_t port_idx, pin_idx;
22		uint8_t gpio_pin;
23		uint32_t function_id;
24	
25		port_idx = AMEBA_GET_PORT_NUM(pin->pinmux);
26		pin_idx = AMEBA_GET_PIN_NUM(pin->pinmux);
27		function_id = AMEBA_GET_PIMNUX_ID(pin->pinmux);
28		gpio_pin = AMEBA_GPIO_PINNAME(port_idx, pin_idx);
29	
30		Pinmux_Config(gpio_pin, function_id);
31	
32		if (pin->pull_up) {
33			PAD_PullCtrl(gpio_pin, GPIO_PuPd_UP);
34			PAD_SleepPullCtrl(gpio_pin, GPIO_PuPd_UP);
35		} else if (pin->pull_down) {
36			PAD_PullCtrl(gpio_pin, GPIO_PuPd_DOWN);
37			PAD_SleepPullCtrl(gpio_pin, GPIO_PuPd_DOWN);
38		} else {
39			PAD_PullCtrl(gpio_pin, GPIO_PuPd_NOPULL);
40			PAD_SleepPullCtrl(gpio_pin, GPIO_PuPd_NOPULL);
41		}
42	
43		/* default slew rate fast */
44		if (pin->slew_rate_slow) {
45			PAD_SlewRateCtrl(gpio_pin, PAD_SlewRate_Slow);
46		}
47	
48		/* Set the PAD driving strength to PAD_DRV_ABILITITY_LOW, default PAD_DRV_ABILITITY_HIGH */
49		if (pin->drive_strength_low) {
50			PAD_DrvStrength(gpio_pin, PAD_DRV_ABILITITY_LOW);
51		}
52	
53		/* default enable digital path input. */
54		if (pin->digital_input_disable) {
55			PAD_InputCtrl(gpio_pin, DISABLE);
56		}
57	
58		/* default enable schmitt */
59		if (pin->schmitt_disable) {
60			PAD_SchmitCtrl(gpio_pin, DISABLE);
61		}
62	
63		if (pin->swd_off) {
64			Pinmux_Swdoff();
65		}
66	
67		return 0;
68	}
69	
70	int pinctrl_configure_pins(const pinctrl_soc_pin_t *pins, uint8_t pin_cnt, uintptr_t reg)
71	{
72		int ret;
73	
74		ARG_UNUSED(reg);
75	
76		for (int i = 0; i < pin_cnt; i++) {
77			ret = ameba_configure_pin(&pins[i]);
78	
79			if (ret < 0) {
80				return ret;
81			}
82		}
83	
