18	#define MODULINO_PIXELS_NUM_LEDS 8
19	
20	/* This is a strip of LC8822 driven by the microcontroller on the Modulino
21	 * board, the start frame is sent automatically, the rest uses the LC8822
22	 * protocol:
23	 * - 4x "1" marker bits
24	 * - 5x brightness bits
25	 * - 3x bytes for B, G, R
26	 */
27	
28	#define MODULINO_PIXELS_MARKER (0xe0 << 24)
29	#define MODULINO_PIXELS_FULL_BRIGHTNESS (0x1f << 24)
30	
31	struct modulino_pixels_config {
32		struct i2c_dt_spec bus;
33	};
34	
35	struct modulino_pixels_data {
36		uint32_t buf[MODULINO_PIXELS_NUM_LEDS];
37	};
38	
39	static int modulino_pixels_update_rgb(const struct device *dev,
40						 struct led_rgb *pixels,
41						 size_t count)
42	{
43		const struct modulino_pixels_config *cfg = dev->config;
44		struct modulino_pixels_data *data = dev->data;
45		int ret;
46	
47		if (count > MODULINO_PIXELS_NUM_LEDS) {
48			return -EINVAL;
49		}
50	
51		for (uint8_t i = 0; i < count; i++) {
52			data->buf[i] = sys_cpu_to_be32(
53					MODULINO_PIXELS_MARKER |
54					MODULINO_PIXELS_FULL_BRIGHTNESS |
55					(pixels[i].b << 16) |
56					(pixels[i].g << 8) |
57					pixels[i].r);
58		}
59	
60		ret = i2c_write_dt(&cfg->bus, (uint8_t *)data->buf, sizeof(data->buf));
61		if (ret < 0) {
62			LOG_ERR("i2c write error: %d", ret);
63			return ret;
64		}
65	
66		return 0;
67	}
68	
69	static size_t modulino_pixels_length(const struct device *dev)
70	{
71		return MODULINO_PIXELS_NUM_LEDS;
72	}
73	
74	static int modulino_pixels_init(const struct device *dev)
75	{
76		const struct modulino_pixels_config *cfg = dev->config;
77		struct modulino_pixels_data *data = dev->data;
78		int ret;
79	
80		if (!i2c_is_ready_dt(&cfg->bus)) {
81			LOG_ERR("Bus device is not ready");
82			return -ENODEV;
83		}
84	
85		for (uint8_t i = 0; i < ARRAY_SIZE(data->buf); i++) {
86			data->buf[i] = sys_cpu_to_be32(MODULINO_PIXELS_MARKER);
87		}
88	
89		/* Reset to all LEDs off */
90		ret = i2c_write_dt(&cfg->bus, (uint8_t *)data->buf, sizeof(data->buf));
91		if (ret < 0) {
92			LOG_ERR("i2c write error: %d", ret);
93			return ret;
94		}
95	
96		return 0;
97	}
98	
99	static DEVICE_API(led_strip, modulino_pixels_api) = {
100		.update_rgb = modulino_pixels_update_rgb,
101		.length = modulino_pixels_length,
102	};
